using System;
using System.Linq;
using CashflowChains.City;
using LocalGame;
using TMPro;
using UnityEngine;
namespace CashflowChains.Presentation {
 public sealed partial class MobileGameApp {
  void WorldResidents(){Base("city-residents");var a=empire.Snapshot;var r=empire.ForecastCity();Studio.Header(root,"", "District census",r.Population+" residents · "+r.Households+" occupied homes",PermanentCityScreen);
   if(r.Population==0){Studio.Image(root,"home",190,280,340,350);Studio.Label(root,"A city starts with a home.",38,650,644,90,40,Studio.Text,TextAlignmentOptions.Center,true);Studio.Label(root,"Build your first house. Residents arrive after construction;empty land creates no people or income.",58,770,604,160,29,Studio.Text,TextAlignmentOptions.Center);Studio.Button(root,"BUILD FIRST HOME",38,1100,644,110,()=>WorldBuildPicker(1,1,0),true);return;}
   var people=CityHousing.Occupancy(empireConfig.City,a.City.Properties,a.City.GridTier,false,a.City.Day,a.City.Region>0).Concat(a.City.Region>0?CityRegion.Households(a.City.Day):new CityHouseholdOccupancy[0]).SelectMany(h=>h.Families).SelectMany(f=>f).ToArray();int[] count={people.Count(p=>p.Age<13),people.Count(p=>p.Age>=13&&p.Age<18),people.Count(p=>p.WorkingAge),people.Count(p=>p.Senior)};string[] label={"CHILDREN","TEENS","WORKING AGE","RETIRED"};
   for(int i=0;i<4;i++){var card=Studio.Box(root,"Age group "+i,38+i%2*330,265+i/2*155,314,140,FlatUI.Hex(i==2?"#176E70":"#143762"));Studio.Label(card,count[i].ToString(),20,80,680,600,52,Studio.Text,TextAlignmentOptions.Center,true);Studio.Label(card,label[i],20,800,680,320,22,Studio.Accent,TextAlignmentOptions.Center,true);}
   Studio.Label(root,"Women & girls: "+r.Women+" · Men & boys: "+r.Men+"\nNon-binary: "+r.NonBinary,38,598,644,90,24,Studio.Text,TextAlignmentOptions.Center);Studio.Label(root,a.City.Region>0?"People power the local economy.":"Different people,different needs.",38,700,644,80,35,Studio.Text,TextAlignmentOptions.Center,true);Studio.Label(root,a.City.Region>0?r.PublicResidents+" residents live in other owners’ homes. "+r.PublicJobs+" residents already work in public and regional operations. Remaining eligible workers can take private jobs. Ages,budgets and preferences limit demand.":"Age,retirement,household budgets and personal interests affect shopping,coffee and entertainment. Children create no coffee orders;retirees do not fill local jobs. Gender is identity,not a price or wage multiplier.",48,810,624,235,28,Studio.Text,TextAlignmentOptions.Center);Studio.Button(root,"INSPECT A HOME",38,1120,644,100,()=>WorldHouseholds((a.City.Properties.FirstOrDefault(p=>empireConfig.City.Business(p.Kind).Population>0&&p.Level>0)?.Id??1000),0),true);Probe();
  }
  void WorldHouseholds(int propertyId,int page){var a=empire.Snapshot;var p=a.City.Properties.FirstOrDefault(b=>b.Id==propertyId)??CityRegion.Property(propertyId);bool publicHome=CityRegion.Building(propertyId)!=null;var h=(publicHome?CityRegion.Households(a.City.Day):CityHousing.Occupancy(empireConfig.City,a.City.Properties,a.City.GridTier,false,a.City.Day,a.City.Region>0)).FirstOrDefault(row=>row.PropertyId==p.Id);var m=Studio.Modal(root,(publicHome?"OTHER OWNER":PropertyLabel(p))+" · HOUSEHOLDS",()=>{if(publicHome)WorldResidents();else WorldPropertyDetails(propertyId);});
   if(h==null||h.Occupied==0){Studio.Label(m,"This home is vacant.\n\nNobody lives here or pays rent yet. Develop jobs,utilities and a useful neighborhood to attract another household.",44,280,632,580,31,Studio.Text,TextAlignmentOptions.Center);return;}
   page=Math.Max(0,Math.Min(h.Occupied-1,page));var family=h.Families[page];Studio.Label(m,"HOME "+(page+1)+" / "+h.Units+" · "+family.Length+" RESIDENTS",44,225,632,70,29,Studio.Accent,TextAlignmentOptions.Center,true);
   for(int i=0;i<family.Length;i++){var person=family[i];float y=330+i*142;var card=Studio.Box(m,"Resident "+person.Id,44,y,632,128,FlatUI.Hex("#173C70"));string role=person.Senior?"Retired":person.WorkingAge?"Working age":person.Age>=13?"Teen":"Child";Studio.Label(card,person.Age+" YEARS · "+(person.Age<18?(person.Gender=="Woman"?"Girl":person.Gender=="Man"?"Boy":person.Gender):person.Gender),24,105,672,410,27,Studio.Text,heavy:true);Studio.Label(card,role+" · "+(person.LikesCoffee?"Coffee fan":person.Adult?"Other drinks":"No coffee orders"),24,665,672,400,23,Studio.Accent);}
   long means=family.Sum(person=>(long)person.DailyBudget),rent=empireConfig.City.Business(p.Kind).Rent;Studio.Label(m,"Daily household budget "+CityMoney(means)+"\nRent "+CityMoney(rent)+" · up to "+CityMoney(Math.Max(0,means-rent))+" left for purchases",44,930,632,130,27,Studio.Text,TextAlignmentOptions.Center);
   if(h.Occupied>1){Studio.Button(m,"PREVIOUS HOME",44,1120,300,90,()=>WorldHouseholds(propertyId,(page+h.Occupied-1)%h.Occupied));Studio.Button(m,"NEXT HOME",360,1120,316,90,()=>WorldHouseholds(propertyId,(page+1)%h.Occupied),true);}else Studio.Button(m,"MY CITY",44,1120,632,90,PermanentCityScreen,true);
  }
 }
}
